import unittest

import mylib as m


class T(unittest.TestCase):
    def test_reverse_words_hidden(self):
        self.assertEqual(m.reverse_words('one'), 'one')
        self.assertEqual(m.reverse_words('x  y'), 'y x')

    def test_average_hidden(self):
        self.assertEqual(m.average([5]), 5)
        self.assertEqual(m.average([-1, 1]), 0)

    def test_clamp_hidden(self):
        self.assertEqual(m.clamp(10, 0, 10), 10)
        self.assertEqual(m.clamp(0, 0, 0), 0)

    def test_first_n_hidden(self):
        self.assertEqual(m.first_n([1, 2], 5), [1, 2])
        self.assertEqual(m.first_n([1, 2, 3], 0), [])

    def test_total_hidden(self):
        self.assertEqual(m.total([]), 0)
        self.assertEqual(m.total([-1, 5]), 4)


if __name__ == '__main__':
    unittest.main()
